export class Matrix {
    public static multiply(a: number[][], b: number[][]): number[][] {
        const rowsA = a.length;
        const colsA = a[0].length;
        const colsB = b[0].length;
        const result: number[][] = [];
        for (let i = 0; i < rowsA; i++) {
            result[i] = [];
            for (let j = 0; j < colsB; j++) {
                let sum = 0;
                for (let k = 0; k < colsA; k++) { sum += a[i][k] * b[k][j]; }
                result[i][j] = sum;
            }
        }
        return result;
    }
}

